{ "calls": [{ "tool": "fetch", "url": "https://example.com" }] }
{ "calls": [{ "tool": "agent", "prompt": "analyze the current project structure" }] }
{ "calls": [{ "tool": "generate_image", "prompt": "architecture diagram", "path": "artifacts/architecture.png" }] }

