import React, { useState, useEffect } from 'react';
import { supabase } from '../../lib/supabase';
import { Lead } from '../../types';
import { Phone, PhoneOff, Clock, Trash2, Mail, Search, Filter } from 'lucide-react';
import { toast } from '../ui/use-toast';
import { cn } from '../../lib/utils';

export default function ColdCallingTab({ campaignId }: { campaignId: string }) {
  const [leads, setLeads] = useState<Lead[]>([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState<'all' | 'gmail' | 'follow_up'>('all');

  useEffect(() => {
    fetchLeads();
  }, [campaignId]);

  const fetchLeads = async () => {
    setLoading(true);
    const { data, error } = await supabase
      .from('campaign_leads')
      .select('lead:leads(*)')
      .eq('campaign_id', campaignId);

    if (data) {
      setLeads(data.map((d: any) => d.lead).filter(Boolean));
    }
    setLoading(false);
  };

  const removeLead = async (leadId: string) => {
    await supabase.from('campaign_leads').delete().eq('campaign_id', campaignId).eq('lead_id', leadId);
    setLeads(leads.filter(l => l.id !== leadId));
    toast({ title: "Lead removed", description: "Lead marked as not interested." });
  };

  const markFollowUp = async (leadId: string) => {
    await supabase.from('leads').update({ status: 'Follow Up' }).eq('id', leadId);
    fetchLeads();
    toast({ title: "Status updated", description: "Lead marked for follow up." });
  };

  const filteredLeads = leads.filter(l => {
    if (filter === 'gmail') return l.email?.toLowerCase().includes('@gmail.com');
    if (filter === 'follow_up') return l.status === 'Follow Up';
    return true;
  });

  return (
    <div className="space-y-4">
      <div className="flex gap-2 mb-4">
        <button onClick={() => setFilter('all')} className={cn("px-4 py-2 rounded-lg text-sm font-bold", filter === 'all' ? "bg-primary text-primary-foreground" : "bg-muted text-muted-foreground")}>All Leads</button>
        <button onClick={() => setFilter('gmail')} className={cn("px-4 py-2 rounded-lg text-sm font-bold", filter === 'gmail' ? "bg-primary text-primary-foreground" : "bg-muted text-muted-foreground")}>Gmail Only</button>
        <button onClick={() => setFilter('follow_up')} className={cn("px-4 py-2 rounded-lg text-sm font-bold", filter === 'follow_up' ? "bg-primary text-primary-foreground" : "bg-muted text-muted-foreground")}>Follow Up</button>
      </div>

      <div className="space-y-2">
        {filteredLeads.map(lead => (
          <div key={lead.id} className="flex items-center justify-between p-4 bg-card border border-border rounded-xl">
            <div>
              <div className="font-bold">{lead.first_name} {lead.last_name || lead.company_name}</div>
              <div className="text-sm text-muted-foreground">{lead.email} • {lead.phone || 'No phone'}</div>
            </div>
            <div className="flex gap-2">
              <button onClick={() => markFollowUp(lead.id)} className="p-2 bg-blue-500/10 text-blue-500 rounded-lg" title="Follow Up Later"><Clock size={16} /></button>
              <button onClick={() => removeLead(lead.id)} className="p-2 bg-destructive/10 text-destructive rounded-lg" title="Not Interested"><PhoneOff size={16} /></button>
            </div>
          </div>
        ))}
        {filteredLeads.length === 0 && !loading && (
          <div className="text-center p-8 text-muted-foreground">No leads found for this filter.</div>
        )}
      </div>
    </div>
  );
}
EOF

